def transform(grid):
    h,w=len(grid),len(grid[0])
    # Detect horizontal/vertical divider coordinates as nearly monochrome lines;
    # ordinary interior color is the most frequent non-divider color.
    rs=[r for r,row in enumerate(grid) if max(row.count(v) for v in range(10))>=w-2]
    cs=[c for c in range(w) if max(sum(grid[r][c]==v for r in range(h)) for v in range(10))>=h-2]
    sep=grid[rs[0]][cs[0]]
    marks={grid[r][c] for r in rs for c in cs if grid[r][c]!=sep}
    freq={v:sum(row.count(v) for row in grid) for v in range(10)}
    fill=max((v for v in range(10) if v!=sep and v not in marks),key=lambda v:freq[v])
    out=[]
    for r0,r1 in zip(rs,rs[1:]):
        row=[]
        for c0,c1 in zip(cs,cs[1:]):
            q=[grid[r0][c0],grid[r0][c1],grid[r1][c0],grid[r1][c1]]
            row.append(q[0] if q[0]!=sep and all(x==q[0] for x in q) else fill)
        out.append(row)
    return out
